/* Buku: static content, scoped renderer, cancellable narration, no AI/backend calls. */
(function(g){
'use strict';
const books=g.GAKU_CERITA_DATA||[],shelves=g.GAKU_CERITA_SHELVES||{n5:{nama:'N5',sub:'Cerita pendek'},dongeng:{nama:'Dongeng',sub:'Buku bergambar'}};
const state={view:'home',rak:'n5',id:null,chapter:0,spread:0,origin:'home',color:true,furi:true,size:22,expanded:false,q:0,pick:null,score:0,options:[],attempt:null,saved:false,error:'',progress:0};
let root=null,seq=0,audio=null,settle=null,timeout=null,playing=-1,playlist=false;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const book=()=>books.find(b=>b.id===state.id),chapter=()=>book()?.bab[state.chapter];
function shuffled(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function levelStats(b){const counts=[0,0,0,0,0,0];for(const k of b.kalimat)for(const t of k.t)if(t[2]>0)counts[t[2]]++;const total=counts.reduce((a,b)=>a+b,0);return counts.map((count,level)=>({level,count,percent:total?count/total*100:0}));}
function offset(){return book().bab.slice(0,state.chapter).reduce((n,b)=>n+b.kalimat.length,0);}
function depth(){const n=state.origin==='list'?2:1;return state.view==='home'?0:state.view==='list'?1:state.view==='detail'?n:state.view==='read'?n+1:n+2;}
function route(){return {view:state.view,rak:state.rak,id:state.id,chapter:state.chapter,spread:state.spread,origin:state.origin,localDepth:depth()};}
function saveRoute(replace=false){g.GakuBuku.onRoute?.(replace);}
function stop(){seq++;playlist=false;playing=-1;clearTimeout(timeout);if(audio){audio.onended=null;audio.onerror=null;audio.pause();audio.removeAttribute('src');audio.load();audio=null;}if(settle){const f=settle;settle=null;f(false);}g.speechSynthesis?.cancel();audioUI();}
function status(text){const el=root?.querySelector('[data-audio-status]');if(el)el.textContent=text;}
function audioUI(){root?.querySelectorAll('[data-audio]').forEach(b=>{const on=Number(b.dataset.audio)===playing;b.textContent=on?'■':'▶';b.setAttribute('aria-label',(on?'Hentikan':'Putar')+' kalimat '+(Number(b.dataset.audio)+1));});const all=root?.querySelector('[data-action="play-all"]');if(all){all.textContent=playlist?'■ Hentikan':'▶ Putar semua';all.setAttribute('aria-pressed',String(playlist));}}
function clip(i,token){const b=book(),c=chapter(),k=c.kalimat[i];return new Promise(resolve=>{let finished=false,fallback=false;const done=ok=>{if(finished)return;finished=true;clearTimeout(timeout);settle=null;if(token===seq){playing=-1;audioUI();}resolve(ok);};settle=done;playing=i;
 if(c.halaman){const page=c.halaman.findIndex(p=>i>=p.dari&&i<p.sampai);if(page>=0&&page!==state.spread){state.spread=page;saveRoute(true);draw();}}
 audioUI();
 const tts=()=>{if(fallback||finished||token!==seq)return;fallback=true;clearTimeout(timeout);if(audio){audio.onended=null;audio.onerror=null;audio.pause();audio=null;}if(!g.speechSynthesis||!g.SpeechSynthesisUtterance){status('Suara belum tersedia. Kamu tetap bisa membaca ceritanya.');done(false);return;}const u=new g.SpeechSynthesisUtterance(k.tts||k.t.map(t=>t[1]||t[0]).join(''));u.lang='ja-JP';u.rate=.8;const v=g.speechSynthesis.getVoices().find(v=>/^ja(?:-|_|$)/i.test(v.lang));if(v)u.voice=v;status('Memakai suara Jepang dari perangkat.');u.onend=()=>done(true);u.onerror=()=>{status('Suara perangkat belum bisa diputar. Coba lagi.');done(false);};timeout=setTimeout(()=>{if(token===seq){g.speechSynthesis.cancel();done(false);status('Suara belum merespons. Coba putar kembali.');}},45000);try{g.speechSynthesis.speak(u);}catch{done(false);status('Suara perangkat belum bisa diputar.');}};
 if(b.audioMode==='device'){tts();return;}
 const path='assets/cerita/'+b.id+'-'+(offset()+i+1)+'.mp3';let checking=false;
 const fail=()=>{if(finished||token!==seq)return;if(audio){audio.onended=null;audio.onerror=null;audio.pause();}status('MP3 belum bisa diputar. Ketuk putar untuk mencoba lagi.');done(false);};
 const missing=async()=>{if(checking||finished||token!==seq)return;checking=true;try{const r=await g.fetch(path,{method:'HEAD'});if(finished||token!==seq)return;if(r.status===404||r.status===410)tts();else fail();}catch{fail();}};
 try{audio=new g.Audio(path);audio.onended=()=>done(true);audio.onerror=missing;audio.onplaying=()=>{clearTimeout(timeout);timeout=setTimeout(fail,90000);};timeout=setTimeout(fail,20000);audio.play()?.catch(e=>{if(e?.name==='NotAllowedError')fail();else missing();});}catch{fail();}
 });}
async function play(i){if(playing===i){stop();return;}g.stopAudio?.();stop();status('');await clip(i,seq);}
async function playAll(){if(playlist){stop();return;}g.stopAudio?.();stop();playlist=true;const token=seq;audioUI();status('');for(let i=0;i<chapter().kalimat.length;i++){if(token!==seq||!await clip(i,token))break;}if(token===seq){playlist=false;playing=-1;audioUI();}}
function reset(){stop();Object.assign(state,{view:'home',id:null,rak:'n5',chapter:0,spread:0,origin:'home',progress:0});}
function list(rak,push=true){if(rak==='bersambung')rak='nene';if(!shelves[rak])return;stop();Object.assign(state,{view:'list',rak,id:null,origin:'list'});if(push)saveRoute();draw(true);}
function detail(id,push=true,entry=0){const b=books.find(b=>b.id===id);if(!b)return;stop();if(state.view==='home'||state.view==='list')state.origin=state.view;Object.assign(state,{id,rak:b.rak,view:'detail',expanded:false,chapter:Math.max(0,Math.min(Number(entry)||0,b.bab.length-1))});if(push)saveRoute();draw(true);}
function read(n=0,push=true){if(!book()?.bab[n])return;stop();Object.assign(state,{view:'read',chapter:n,spread:0,progress:0});if(push)saveRoute();draw(true);}
function spread(n){const pages=chapter()?.halaman;if(!pages||n<0||n>=pages.length)return;stop();state.spread=n;saveRoute(true);draw(true);}
function startQuiz(){if(!chapter())return;stop();Object.assign(state,{view:'quiz',q:0,pick:null,score:0,attempt:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),saved:false,error:''});prepare();saveRoute();draw(true);}
function prepare(){const q=chapter().kuis[state.q];state.options=shuffled(q.opsi.map((text,index)=>({text,correct:index===q.benar})));}
function choose(i){if(state.view!=='quiz'||state.pick!==null||!state.options[i])return;state.pick=i;if(state.options[i].correct)state.score++;root?.querySelectorAll('[data-choice]').forEach((el,n)=>{el.disabled=true;el.classList.toggle('bk-correct',state.options[n].correct);el.classList.toggle('bk-wrong',n===i&&!state.options[n].correct);});const next=root?.querySelector('[data-action="next"]');if(next)next.disabled=false;const feedback=root?.querySelector('[data-feedback]');if(feedback)feedback.textContent=state.options[i].correct?'Benar. Kamu memahami bagian ini.':'Belum tepat. Jawaban yang benar: '+state.options.find(o=>o.correct).text;}
function record(){if(state.saved)return;if(g.GakuHistory){const b=book(),c=chapter(),entry={type:'Buku',detail:b.judul+' · Bab '+c.no,time:new Date().toISOString(),level:b.level,buku:{id:state.id,chapter:state.chapter,score:state.score,total:c.kuis.length,attempt:state.attempt}};if(g.GakuHistory.add(entry)){state.saved=true;state.error='';g.GakuBuku.onSaved?.()}else state.error='Hasil belum tersimpan di perangkat ini. Kamu bisa mencoba menyimpan kembali.';return;}try{const key='gaku-ui-history',history=JSON.parse(g.localStorage.getItem(key)||'[]');if(!Array.isArray(history))throw Error('history');if(!history.some(h=>h.buku?.attempt===state.attempt)){history.unshift({type:'Buku',detail:book().judul+' · Bab '+chapter().no+' · '+state.score+'/'+chapter().kuis.length,time:new Date().toISOString(),buku:{id:state.id,chapter:state.chapter,score:state.score,total:chapter().kuis.length,attempt:state.attempt}});g.localStorage.setItem(key,JSON.stringify(history.slice(0,40)));}state.saved=true;state.error='';g.GakuBuku.onSaved?.();}catch{state.error='Hasil belum tersimpan di perangkat ini. Kamu bisa mencoba menyimpan kembali.';}}
function next(){if(state.view!=='quiz'||state.pick===null)return;if(state.q+1<chapter().kuis.length){state.q++;state.pick=null;prepare();draw(true);}else{state.view='done';record();saveRoute(true);draw(true);}}
function restore(r){stop();if(!r||!['home','list','detail','read','quiz','done'].includes(r.view)){reset();return;}if(r.view==='home'){reset();return;}if(r.view==='list'){r={...r,rak:r.rak==='bersambung'?'nene':r.rak};if(shelves[r.rak])Object.assign(state,{view:'list',rak:r.rak,origin:'list',id:null});else reset();return;}const b=books.find(b=>b.id===r.id);if(!b){reset();return;}Object.assign(state,{id:b.id,rak:b.rak,origin:r.origin==='list'?'list':'home',chapter:Math.max(0,Math.min(Number(r.chapter)||0,b.bab.length-1)),spread:Number(r.spread)||0,view:r.view});const count=chapter().halaman?.length||1;state.spread=Math.max(0,Math.min(state.spread,count-1));if(['quiz','done'].includes(r.view))state.view='read';}
function cover(b,large=false){return `<div class="bk-cover ${large?'bk-cover-large':''}">${b.cover?`<img src="${esc(b.cover)}" alt="Sampul ${esc(b.judul)}" loading="lazy" decoding="async" width="600" height="900" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="bk-cover-fallback" hidden aria-hidden="true">${esc(b.ic)}</span>`:`<span class="bk-cover-fallback" aria-hidden="true">${esc(b.ic)}</span>`}<span class="bk-cover-title" lang="ja" aria-hidden="true">${esc(b.jp)}</span></div>`;}
function card(b,vertical=false,part=null){const serial=Number.isInteger(part),c=serial?b.bab[part]:null;return `<button class="bk-book ${vertical?'bk-book-list':''}" data-book="${esc(b.id)}" ${serial?`data-entry-chapter="${part}"`:''} aria-label="Buka ${esc(b.judul)}${serial?' · Bagian '+c.no:''}">${cover(b)}<div class="bk-book-copy"><span class="bk-badge">${esc(b.level)} · ${serial?'Bagian '+c.no+' / '+b.bab.length:b.bab.length+' bab'}</span><h3>${serial?'Bagian '+c.no+' · '+esc(c.judul):esc(b.judul)}</h3><p ${serial?'':'lang="ja"'}>${serial?esc(b.judul):esc(b.jp)}</p></div></button>`;}
function shelfCards(id,vertical=false){return books.filter(b=>b.rak===id).map(b=>b.serial?b.bab.map((_,i)=>card(b,vertical,i)).join(''):card(b,vertical)).join('');}
function home(){return `<div class="bk-welcome"><span class="bk-kicker">SEBUAH CERITA, KATA-KATA BARU</span><h2>Temukan dunia<br>di setiap halaman.</h2><p>Baca pelan-pelan. Buka arti saat perlu,<br>dan biarkan ceritanya membawamu.</p><span class="bk-welcome-symbol" aria-hidden="true">本<span>✦</span></span></div>${Object.entries(shelves).map(([id,s])=>`<section class="bk-shelf-section"><div class="bk-section-title"><div><h2>${esc(s.nama)}</h2><p>${esc(s.sub)}</p></div><button data-shelf="${esc(id)}" aria-label="Lihat semua buku ${esc(s.nama)}">Lihat semua →</button></div><div class="bk-shelf" aria-label="Rak ${esc(s.nama)}">${shelfCards(id)}</div></section>`).join('')}<details class="bk-sources"><summary>Jelajahi referensi bacaan</summary><p>Temukan bacaan lainnya di <a href="https://www.shinobi-japanese.com/id/japanese-stories" target="_blank" rel="noopener noreferrer">Shinobi</a> dan <a href="https://runruneando.com/id-id/cerita-dari/jepang?orden=recientes" target="_blank" rel="noopener noreferrer">Runruneando</a>. Buku di sini memakai ilustrasi baru dan teks pembelajaran sendiri atau data yang kamu berikan.</p></details>`;}
function detailScreen(){const b=book(),long=b.deskripsi.length>150;return `<button class="bk-back" data-action="back">‹ ${state.origin==='list'?'Daftar buku':'Rak buku'}</button><div class="bk-detail"><div>${cover(b,true)}</div><div><span class="bk-kicker">${esc(shelves[b.rak].nama)} · ${b.bab.length} ${b.serial?'BAGIAN':'BAB'}</span><h2>${esc(b.judul)}</h2><p lang="ja" class="bk-subtitle">${esc(b.jp)}</p><span class="bk-badge">${esc(b.level)}</span><h3>Tentang cerita ini</h3>${b.audioMode==='device'?'<p class="bk-note">Audio memakai suara Jepang dari perangkat.</p>':''}<p class="bk-description" data-description>${esc(long&&!state.expanded?b.deskripsi.slice(0,150)+'…':b.deskripsi)}</p>${long?`<button class="bk-link" data-action="description" aria-expanded="${state.expanded}">${state.expanded?'Lebih sedikit':'Lebih Banyak'}</button>`:''}<button class="bk-primary" data-chapter="${b.serial?state.chapter:0}">${b.serial?'Baca bagian '+(state.chapter+1):'Mulai baca'} →</button></div></div><section class="bk-chapter-list"><h3>Daftar ${b.serial?'bagian':'bab'}</h3>${b.bab.map((c,i)=>`<button data-chapter="${i}" ${b.serial&&i===state.chapter?'aria-current="true"':''}><span class="bk-chapter-number">${String(c.no).padStart(2,'0')}</span><span><b>${esc(c.judul)}</b><small>${c.kalimat.length} kalimat${c.halaman?' · '+c.halaman.length+' halaman bergambar':''}</small></span><span>→</span></button>`).join('')}</section>${b.serial?`<p class="bk-credit">${esc(b.kredit||b.sumber?.catatan)}</p>`:''}${b.sumber?`<details class="bk-sources"><summary>Asal cerita</summary><p>${esc(b.sumber.catatan)} ${b.sumber.url?`<a href="${esc(b.sumber.url)}" target="_blank" rel="noopener noreferrer">${esc(b.sumber.label||'Rujukan alur klasik')} ↗</a>`:''}</p></details>`:''}`;}
function tokens(t){return t.map(([text,furi,level])=>`<span class="bk-token bk-lv-${level}" data-level="${level}">${furi?`<ruby>${esc(text)}<rt>${esc(furi)}</rt></ruby>`:esc(text)}</span>`).join('');}
function sentence(k,i){return `<article class="bk-sentence"><p class="bk-jp" lang="ja">${tokens(k.t)}</p><div class="bk-sentence-actions"><button data-translate="${i}" aria-expanded="false" aria-controls="bk-tr-${i}">Terjemahkan</button><button data-explain="${i}" aria-expanded="false" aria-controls="bk-ex-${i}">Jelaskan</button><button data-audio="${i}" aria-label="Putar kalimat ${i+1}">▶</button></div><p class="bk-translation" id="bk-tr-${i}" hidden>${esc(k.id)}</p><div class="bk-explanation" id="bk-ex-${i}" hidden>${k.jelas.map(x=>`<div><strong lang="ja">${esc(x.pola)}</strong><b>${esc(x.arti)}</b><p>${esc(x.catatan)}</p></div>`).join('')}</div></article>`;}
function toolbar(){return `<div class="bk-reader-tools" aria-label="Bantuan membaca"><button data-action="back" aria-label="Kembali ke halaman buku">‹ Buku</button><button data-toggle="color" aria-pressed="${state.color}" aria-label="Warna level kata">色 <span>Warna</span></button><button data-toggle="furi" aria-pressed="${state.furi}" aria-label="Tampilkan furigana">ふ <span>Furigana</span></button><button data-action="size" aria-label="Ukuran huruf, saat ini ${state.size} piksel">Aa <span>${state.size}</span></button><button data-action="play-all" aria-pressed="false">▶ Putar semua</button><details class="bk-chapter-menu"><summary>Daftar ${book().serial?'bagian':'bab'} ▾</summary>${book().bab.map((c,i)=>`<button data-change-chapter="${i}" aria-current="${i===state.chapter?'true':'false'}">${c.no}. ${esc(c.judul)}</button>`).join('')}</details></div>`;}
function levelBar(){const rows=levelStats(chapter()).filter(x=>x.count>0);return `<section class="bk-levels"><h3>Jejak kata di ${book().serial?'bagian':'bab'} ini</h3><div class="bk-level-bar">${rows.map(x=>`<span class="bk-level-fill bk-level-${x.level}" style="width:${x.percent}%" title="N${x.level}: ${x.count} token"></span>`).join('')}</div><div class="bk-level-legend">${rows.map(x=>`<span><i class="bk-level-${x.level}"></i>N${x.level} · ${Math.round(x.percent)}%</span>`).join('')}</div><p>Persentase token bertanda level, tanpa partikel dan tanda baca. Warna adalah panduan belajar.</p></section>`;}
function readScreen(){const b=book(),c=chapter(),p=c.halaman?.[state.spread];return `${toolbar()}<div class="bk-reading ${state.color?'bk-color':''} ${state.furi?'':'bk-no-furi'}" style="--bk-font:${state.size}px"><header class="bk-reading-title"><span class="bk-kicker">${esc(b.judul)} · ${b.serial?'BAGIAN':'BAB'} ${c.no}</span><h2>${esc(c.judul)}</h2><div class="bk-progress" aria-label="Progres membaca"><span data-progress-label>${state.progress}% selesai</span><div><i data-progress style="width:${state.progress}%"></i></div></div><p data-audio-status class="bk-audio-status" role="status"></p></header><div class="bk-reader-content" data-reader-content>${p?`<section class="bk-spread" aria-label="Halaman ${state.spread+1} dari ${c.halaman.length}"><figure><img src="${esc(p.gambar)}" alt="${esc(p.alt)}" width="960" height="640" decoding="async"><figcaption>${esc(b.judul)} · ${state.spread+1} / ${c.halaman.length}</figcaption></figure><div class="bk-paper">${c.kalimat.slice(p.dari,p.sampai).map((k,i)=>sentence(k,p.dari+i)).join('')}</div></section><nav class="bk-page-controls" aria-label="Halaman buku"><button data-page="${state.spread-1}" ${state.spread===0?'disabled':''}>‹ Sebelumnya</button><span>${state.spread+1} / ${c.halaman.length}</span><button data-page="${state.spread+1}" ${state.spread+1===c.halaman.length?'disabled':''}>Berikutnya ›</button></nav>`:`<div class="bk-prose">${c.kalimat.map(sentence).join('')}</div>`}</div>${b.serial?serialEnd():''}${levelBar()}${b.serial?'':!p||state.spread===c.halaman.length-1?'<button class="bk-primary bk-finish-chapter" data-action="quiz">Selesaikan bab →</button>':'<p class="bk-note">Balik halaman untuk melanjutkan kisahnya.</p>'}</div>`;}
function serialEnd(){const b=book(),last=state.chapter===b.bab.length-1;return `<footer class="bk-serial-end">${last?`<p class="bk-story-end">TAMAT</p><p class="bk-credit">${esc(b.kredit||b.sumber?.catatan)}</p>`:'<p class="bk-note">Ambil jeda sebentar, atau lanjutkan kisahnya.</p>'}<nav aria-label="Lanjut membaca">${state.chapter>0?`<button class="bk-back" data-change-chapter="${state.chapter-1}">‹ Bagian sebelumnya</button>`:''}${last?'<button class="bk-primary" data-action="home">Kembali ke rak buku →</button>':`<button class="bk-primary" data-change-chapter="${state.chapter+1}">Bagian ${state.chapter+2} →</button>`}</nav><details class="bk-optional-quiz"><summary>Ingin mengecek pemahaman?</summary><p>Tiga pertanyaan tentang bagian ini. Kamu juga bisa langsung melanjutkan cerita.</p><button class="bk-back" data-action="quiz">Coba latihan bagian ini</button></details></footer>`;}

function quizScreen(){const q=chapter().kuis[state.q];return `<button class="bk-back" data-action="back">‹ Kembali membaca</button><section class="bk-quiz"><span class="bk-kicker">CEK PEMAHAMAN · ${state.q+1} DARI ${chapter().kuis.length}</span><h2 lang="ja">${esc(q.q)}</h2><div>${state.options.map((o,i)=>`<button class="bk-option ${state.pick!==null?(o.correct?'bk-correct':i===state.pick?'bk-wrong':''):''}" data-choice="${i}" ${state.pick!==null?'disabled':''}><span>${i+1}</span>${esc(o.text)}</button>`).join('')}</div><p class="bk-feedback" data-feedback role="status">${state.pick===null?'Pilih satu jawaban.':state.options[state.pick].correct?'Benar.':'Jawaban yang benar: '+esc(state.options.find(o=>o.correct).text)}</p><button class="bk-primary" data-action="next" ${state.pick===null?'disabled':''}>${state.q+1===chapter().kuis.length?'Lihat hasil':'Berikutnya →'}</button></section>`;}
function doneScreen(){return `<section class="bk-done"><span class="bk-done-star" aria-hidden="true">✦</span><span class="bk-kicker">${book().serial?'BAGIAN':'BAB'} SELESAI</span><h2>Halaman terakhir,<br>kata-kata baru.</h2><p>${esc(book().judul)} · ${esc(chapter().judul)}</p><strong>${state.score} <small>/ ${chapter().kuis.length}</small></strong><p>jawaban benar</p><p class="bk-error" role="status">${esc(state.error)}</p>${state.error?'<button class="bk-back" data-action="save">Coba simpan lagi</button>':''}<div>${book().serial&&state.chapter+1<book().bab.length?`<button class="bk-primary" data-change-chapter="${state.chapter+1}">Bagian ${state.chapter+2} →</button>`:''}<button class="bk-primary" data-action="home">Rak buku →</button><button class="bk-back" data-action="back">Baca kembali</button></div></section>`;}
function content(){if(state.view==='home')return home();if(state.view==='list')return `<button class="bk-back" data-action="back">‹ Rak buku</button><div class="bk-section-title"><div><span class="bk-kicker">SEMUA BUKU</span><h2>${esc(shelves[state.rak].nama)}</h2><p>${esc(shelves[state.rak].sub)}</p></div></div><div class="bk-list">${shelfCards(state.rak,true)}</div>`;if(!book()){reset();return home();}if(state.view==='detail')return detailScreen();if(state.view==='read')return readScreen();if(state.view==='quiz')return quizScreen();return doneScreen();}
function screen(){return '<section id="buku-root" class="bk-app" aria-label="Buku belajar bahasa Jepang">'+content()+'</section>';}
function draw(focus=false){if(!root?.isConnected)return;root.innerHTML=content();audioUI();if(focus){root.querySelector('h2')?.setAttribute('tabindex','-1');root.querySelector('h2')?.focus({preventScroll:true});g.scrollTo?.({top:0,behavior:'instant'});}updateProgress();}
function updateProgress(){if(state.view!=='read'||!root)return;const el=root.querySelector('[data-reader-content]');if(!el)return;const r=el.getBoundingClientRect(),available=g.innerHeight||700;const part=r.height<=available?1:Math.max(0,Math.min(1,(available-r.top)/(r.height)));const pages=chapter().halaman?.length||1;const value=Math.round((state.spread+part)/pages*100);state.progress=Math.max(state.progress,value);const label=root.querySelector('[data-progress-label]'),bar=root.querySelector('[data-progress]');if(label)label.textContent=state.progress+'% selesai';if(bar)bar.style.width=state.progress+'%';}
function click(e){const b=e.target.closest('button');if(!b||b.disabled||!root.contains(b))return;const d=b.dataset;if(d.book){detail(d.book,true,Number(d.entryChapter)||0);return;}if(d.shelf){list(d.shelf);return;}if('chapter'in d){read(Number(d.chapter));return;}if('changeChapter'in d){read(Number(d.changeChapter),false);saveRoute(true);return;}if('page'in d){spread(Number(d.page));return;}if('choice'in d){choose(Number(d.choice));return;}if('audio'in d){play(Number(d.audio));return;}if(d.toggle){state[d.toggle]=!state[d.toggle];b.setAttribute('aria-pressed',String(state[d.toggle]));root.querySelector('.bk-reading').classList.toggle(d.toggle==='color'?'bk-color':'bk-no-furi',d.toggle==='color'?state.color:!state.furi);return;}if('translate'in d||'explain'in d){const tr='translate'in d,id=Number(tr?d.translate:d.explain),el=root.querySelector('#bk-'+(tr?'tr':'ex')+'-'+id);el.hidden=!el.hidden;b.setAttribute('aria-expanded',String(!el.hidden));return;}const a=d.action;if(a==='back'){if(g.GakuBuku.onBack)g.GakuBuku.onBack();else{state.view=state.view==='read'?'detail':'home';draw(true);}}if(a==='home'){if(g.GakuBuku.onHome)g.GakuBuku.onHome();else{reset();draw(true);}}if(a==='size'){state.size=state.size===26?18:state.size+4;root.querySelector('.bk-reading').style.setProperty('--bk-font',state.size+'px');b.setAttribute('aria-label','Ukuran huruf, saat ini '+state.size+' piksel');b.innerHTML='Aa <span>'+state.size+'</span>';}if(a==='description'){state.expanded=!state.expanded;const el=root.querySelector('[data-description]'),text=book().deskripsi;el.textContent=state.expanded?text:text.slice(0,150)+'…';b.textContent=state.expanded?'Lebih sedikit':'Lebih Banyak';b.setAttribute('aria-expanded',String(state.expanded));}if(a==='play-all')playAll();if(a==='quiz')startQuiz();if(a==='next')next();if(a==='save'){record();draw(true);}}
function sync(active){if(!active){stop();root=null;return;}const next=document.getElementById('buku-root');if(root!==next){stop();root=next;root?.addEventListener('click',click);}updateProgress();}
g.GakuBuku={screen,sync,stop,reset,list,detail,read,spread,startQuiz,choose,next,play,playAll,getRoute:route,restore,levelStats};
g.addEventListener('scroll',updateProgress,{passive:true});g.addEventListener('resize',updateProgress);g.addEventListener('pagehide',stop);
})(window);
